import { Component } from "@angular/core";
import { FormGroup, FormBuilder, Validators } from "@angular/forms";
import { AuthService } from "../../services/auth.service";

@Component({
  selector: "app-login",
  templateUrl: "./login.component.html",
  styleUrls: ["./login.component.css"],
})
export class LoginComponent {
  loginForm!: FormGroup;
  errorMessage?: string;
  successMessage?: string;

  constructor(
    private formBuilder: FormBuilder,
    private authService: AuthService,
  ) {}

  ngOnInit() {
    this.loginForm = this.formBuilder.group({
      username: ["", [Validators.required, Validators.minLength(5)]],
      password: ["", [Validators.required, Validators.minLength(8)]],
    });
  }

  get f() {
    return this.loginForm.controls;
  }

  onSubmit(formDirective: any) {
    // const formData = new FormData(formDirective.currentTarget);
    const formData = {
      username: formDirective.currentTarget.username.value,
      password: formDirective.currentTarget.password.value,
    };

    if (formDirective.submitted && this.loginForm.invalid) {
      this.errorMessage = "Usuario o contraseña no cumple con las validaciones";
      return;
    }

    this.authService.login(formData.username, formData.password).subscribe({
      next: (resp) => {
        this.successMessage = resp.message;
        console.log("respuesta del servidor:", resp);
      },
      error: (err) => {
        this.errorMessage = err.message;
        console.log("respuesta del servidor:", err);
      },
    });

    // Aquí iría la lógica de autenticación
    console.log("formulario enviado:", formData);

    setTimeout(() => {
      this.clearMessages();
    }, 3000);
  }

  clearMessages() {
    this.errorMessage = undefined;
    this.successMessage = undefined;
  }
}
